#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long k;
    cin >> k;

    const long long MOD = 1000000007;
    vector<long long> row(k + 1, 0);
    row[0] = 1;
    for (long long i = 1; i <= k; i++) {
        for (long long j = i; j >= 1; j--) {
            row[j] = (row[j] + row[j - 1]) % MOD;
        }
    }
    for (long long j = 0; j <= k; j++) cout << (j ? " " : "") << row[j];
    cout << "\n";

    return 0;
}

